before.lib/client.ex:
defmodule Client do
  @doc "Read-only lookup. At most three attempts, including the first."
  def lookup(transport), do: Retry.run(transport, 3)
end

before.lib/lookup.ex:
defmodule Lookup do
  @moduledoc "An operation may make at most four downstream requests."
  def run(transport), do: Client.lookup(transport)
end

after.lib/client.ex:
defmodule Client do
  @doc "Read-only lookup. At most three attempts, including the first."
  def lookup(transport), do: Retry.run(transport, 3)
end

after.lib/lookup.ex:
defmodule Lookup do
  @moduledoc "An operation may make at most four downstream requests."
  def run(transport), do: Retry.run(fn -> Client.lookup(transport) end, 4)
end
